// ─── SCENE 2: Only a fraction are used (0:07–0:17) = 250 frames ─────────────

const SceneFractionUsed: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const totalBars = 20;
  const usedCount = 3;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 32,
          paddingBottom: 160,
        }}
      >
        {/* Bar chart showing most hashtags unused */}
        <div
          style={{
            display: "flex",
            alignItems: "flex-end",
            gap: 28,
            height: 700,
          }}
        >
          {Array.from({ length: totalBars }).map((_, i) => {
            const isUsed = i < usedCount;
            const delay = 10 + i * 8;
            const barProgress = spring({ frame, fps, delay, config: { damping: 200 } });
            const barHeight = isUsed
              ? interpolate(Math.pow(usedCount - i, 1.5) / Math.pow(usedCount, 1.5), [0, 1], [350, 650])
              : interpolate(i / totalBars, [0, 1], [80, 20]);
            const animatedHeight = interpolate(barProgress, [0, 1], [0, barHeight]);

            return (
              <div
                key={i}
                style={{
                  width: 72,
                  height: animatedHeight,
                  borderRadius: "12px 12px 0 0",
                  backgroundColor: isUsed
                    ? COLORS.pink
                    : "rgba(255,255,255,0.08)",
                  opacity: isUsed ? 1 : 0.5,
                  boxShadow: isUsed ? `0 0 40px ${COLORS.pink}66` : "none",
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* Label */}
        {(() => {
          const labelProgress = spring({ frame, fps, delay: 90, config: { damping: 200 } });
          return (
            <div
              style={{
                opacity: labelProgress,
                transform: `translateY(${interpolate(labelProgress, [0, 1], [40, 0])}px)`,
                display: "flex",
                alignItems: "center",
                gap: 32,
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                <div style={{ width: 32, height: 32, borderRadius: 8, backgroundColor: COLORS.pink }} />
                <span style={{ fontSize: 48, color: COLORS.lightPink, fontWeight: 600 }}>Actually used</span>
              </div>
              <div style={{ width: 2, height: 48, backgroundColor: "rgba(255,255,255,0.15)" }} />
              <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                <div style={{ width: 32, height: 32, borderRadius: 8, backgroundColor: "rgba(255,255,255,0.08)" }} />
                <span style={{ fontSize: 48, color: COLORS.mutedPurple, fontWeight: 600 }}>Rarely used</span>
              </div>
            </div>
          );
        })()}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

