// ─── SCENE 5: Buried vs Discovered (0:33–0:51) = 450 frames ─────────────────

const SceneBuriedVsDiscovered: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Phase 1: Buried (0–225), Phase 2: Discovered (225–450)
  const phase2Start = 225;
  const isPhase2 = frame >= phase2Start;

  const phase1Opacity = interpolate(frame, [180, 210], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const phase2Opacity = interpolate(frame, [210, 240], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Buried: posts sinking
  const buriedPosts = [
    { tag: "#wronghashtag", delay: 10 },
    { tag: "#unused", delay: 20 },
    { tag: "#toobroad", delay: 30 },
  ];

  // Discovered: posts rising
  const discoveredPosts = [
    { tag: "#perfectfit", delay: 0 },
    { tag: "#targeted", delay: 15 },
    { tag: "#trending", delay: 30 },
  ];

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      {/* PHASE 1: BURIED */}
      <AbsoluteFill
        style={{
          opacity: phase1Opacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 160,
          gap: 48,
        }}
      >
        {/* Downward arrow */}
        {(() => {
          const p = spring({ frame, fps, delay: 10, config: { damping: 200 } });
          return (
            <div
              style={{
                opacity: p,
                transform: `scale(${interpolate(p, [0, 1], [0.5, 1])})`,
              }}
            >
              <svg width="180" height="180" viewBox="0 0 24 24" fill="none">
                <circle cx="12" cy="12" r="11" fill="rgba(239,68,68,0.12)" stroke="rgba(239,68,68,0.3)" strokeWidth="1.5" />
                <path d="M12 8v8M8 12l4 4 4-4" stroke="#EF4444" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </div>
          );
        })()}

        <div style={{ display: "flex", flexDirection: "column", gap: 28, alignItems: "center" }}>
          {buriedPosts.map((post, i) => {
            const p = spring({ frame, fps, delay: post.delay + 15, config: { damping: 200 } });
            const sinkOffset = interpolate(frame, [0, 175], [0, 20 + i * 15], { extrapolateRight: "clamp" });
            return (
              <div
                key={i}
                style={{
                  opacity: interpolate(p, [0, 1], [0, 0.5 - i * 0.1]),
                  transform: `translateY(${sinkOffset}px) scale(${interpolate(p, [0, 1], [0.8, 1 - i * 0.05])})`,
                  backgroundColor: "rgba(239,68,68,0.06)",
                  border: "2px solid rgba(239,68,68,0.15)",
                  borderRadius: 20,
                  padding: "28px 64px",
                  fontSize: 52 - i * 6,
                  fontWeight: 700,
                  color: `rgba(239,68,68,${0.7 - i * 0.15})`,
                }}
              >
                {post.tag}
              </div>
            );
          })}
        </div>

        <div
          style={{
            marginTop: 20,
            fontSize: 48,
            fontWeight: 700,
            color: "#EF4444",
            opacity: interpolate(
              spring({ frame, fps, delay: 80, config: { damping: 200 } }),
              [0, 1], [0, 1]
            ),
          }}
        >
          Lost in the noise
        </div>
      </AbsoluteFill>

      {/* PHASE 2: DISCOVERED */}
      <AbsoluteFill
        style={{
          opacity: phase2Opacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 160,
          gap: 48,
        }}
      >
        {/* Upward arrow */}
        <div
          style={{
            opacity: phase2Opacity,
            transform: `scale(${interpolate(phase2Opacity, [0, 1], [0.5, 1])})`,
          }}
        >
          <svg width="180" height="180" viewBox="0 0 24 24" fill="none">
            <circle cx="12" cy="12" r="11" fill="rgba(74,222,128,0.12)" stroke="rgba(74,222,128,0.3)" strokeWidth="1.5" />
            <path d="M12 16V8M8 12l4-4 4 4" stroke={COLORS.green} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 28, alignItems: "center" }}>
          {discoveredPosts.map((post, i) => {
            const localFrame = Math.max(0, frame - phase2Start);
            const p = spring({ frame: localFrame, fps, delay: post.delay + 10, config: { damping: 200 } });
            const riseOffset = interpolate(p, [0, 1], [30, 0]);
            return (
              <div
                key={i}
                style={{
                  opacity: p,
                  transform: `translateY(${riseOffset}px) scale(${interpolate(p, [0, 1], [0.85, 1])})`,
                  backgroundColor: "rgba(74,222,128,0.08)",
                  border: `2px solid rgba(74,222,128,${0.4 - i * 0.1})`,
                  borderRadius: 20,
                  padding: "28px 64px",
                  fontSize: 52,
                  fontWeight: 700,
                  color: COLORS.green,
                  boxShadow: `0 0 60px rgba(74,222,128,${0.15 - i * 0.04})`,
                }}
              >
                {post.tag}
              </div>
            );
          })}
        </div>

        <div
          style={{
            marginTop: 20,
            fontSize: 48,
            fontWeight: 700,
            color: COLORS.green,
            opacity: interpolate(
              Math.max(0, frame - phase2Start - 60),
              [0, 25], [0, 1],
              { extrapolateRight: "clamp" }
            ),
          }}
        >
          Reaching your audience
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

